/**
 * @fileoverview Test the usage of deprecated methods
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-method-call'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-deprecated-method-call', rule, {

    valid: [
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.Array.clean(['a', null, '', 'b']);
                Ext.Array.max([1, 5, 3]);
            `,
        },
        {
            settings: {
                extjs: {
                    version: '4'
                }
            },
            code: `
                Ext.define('Ext.ux.desktop.TrayClock', {
                    extend: 'Ext.toolbar.TextItem',
                    updateTime: function () {
                        var me = this;
                        me.setText(text);   // setText existing in 4 so this is valid
                    }
                });
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '5.1'
                }
            },
            code: `
                Ext.define('Ext.ux.desktop.TrayClock', {
                    extend: 'Ext.toolbar.TextItem',
                    updateTime: function () {
                        var me = this;
                        // setText was deprecated in 5.1 so this is invalid
                        me.setText(text);
                    }
                });
            `,
            errors: [
                { message: /Call to deprecated method 'setText' found for 'Ext.toolbar.TextItem'.*/ }
            ],
            output: `
                Ext.define('Ext.ux.desktop.TrayClock', {
                    extend: 'Ext.toolbar.TextItem',
                    updateTime: function () {
                        var me = this;
                        // setText was deprecated in 5.1 so this is invalid
                        me.update(text);
                    }
                });
            `
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4.1',
                    toVersion: '6'
                }
            },
            code: `
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    fields: ['first', 'last']
                });
                Ext.ModelManager.create({
                    first: 'Jack',
                    last: 'Ratcliff'
                }, 'User');
            `,
            errors: [
                { message: /Call to deprecated method 'create' found for 'Ext.ModelManager'.*/ }
            ]
        },
        {
            code: `
                Ext.clean(['a', null, '', 'b']);
                Ext.max([1, 5, 3]);

                // TODO - add support for the following
                var method = 'clean';
                Ext[method](['a', null, '', 'b']);
            `,
            output: `
                Ext.Array.clean(['a', null, '', 'b']);
                Ext.Array.max([1, 5, 3]);

                // TODO - add support for the following
                var method = 'clean';
                Ext[method](['a', null, '', 'b']);
            `,
            errors: [
                { message: /Call to deprecated method 'clean' found for 'Ext'.*/ },
                { message: /Call to deprecated method 'max' found for 'Ext'.*/ }
            ]
        },
        {
            code: `
                // testing deprecated 'createWidget' method
                Ext.createWidget('window', {});

                // testing deprecated 'addClass' method
                Ext.create('panel', {}).addClass('abc');

                // testing deprecated 'addClass' method from a chained Ext.create() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'button';
                        Ext.create(type, {}).addClass('abc');
                    }
                });

                // testing deprecated 'addClass' method from a chained Ext.widget() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'container';
                        Ext.widget(type, {}).addClass('abc');
                    }
                });

                // testing deprecated 'addClass' method from a chained Ext.create() call that uses a variable for the className
                Ext.define('MyClass', {
                    constructor: function () {
                        var className = 'Ext.grid.Panel';
                        Ext.create(className, {}).addClass('abc');
                    }
                });

                // testing deprecated 'addClass' method from a chained new xClass() call that uses a variable for the xClass
                Ext.define('MyClass', {
                    constructor: function () {
                        var xClass = Ext.tree.Panel;
                        new xClass().addClass('abc');
                    }
                });
            `,
            output: `
                // testing deprecated 'createWidget' method
                Ext.widget('window', {});

                // testing deprecated 'addClass' method
                Ext.create('panel', {}).addClass('abc');

                // testing deprecated 'addClass' method from a chained Ext.create() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'button';
                        Ext.create(type, {}).addClass('abc');
                    }
                });

                // testing deprecated 'addClass' method from a chained Ext.widget() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'container';
                        Ext.widget(type, {}).addClass('abc');
                    }
                });

                // testing deprecated 'addClass' method from a chained Ext.create() call that uses a variable for the className
                Ext.define('MyClass', {
                    constructor: function () {
                        var className = 'Ext.grid.Panel';
                        Ext.create(className, {}).addClass('abc');
                    }
                });

                // testing deprecated 'addClass' method from a chained new xClass() call that uses a variable for the xClass
                Ext.define('MyClass', {
                    constructor: function () {
                        var xClass = Ext.tree.Panel;
                        new xClass().addClass('abc');
                    }
                });
            `,
            errors: [
                { message: /Call to deprecated method 'createWidget' found for 'Ext'.*/ },
                { message: /Call to deprecated method 'addClass' found for 'Ext.panel.Panel'.*/ },
                { message: /Call to deprecated method 'addClass' found for 'Ext.button.Button'.*/ },
                { message: /Call to deprecated method 'addClass' found for 'Ext.container.Container'.*/ },
                { message: /Call to deprecated method 'addClass' found for 'Ext.grid.Panel'.*/ },
                { message: /Call to deprecated method 'addClass' found for 'Ext.tree.Panel'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    someCustomMethod: function () {
                        this.doComponentLayout();
                    },
                    someCustomMethod: function () {
                        var me = this;
                        me.forceComponentLayout();
                    }
                });
            `,
            errors: [
                { message: /Call to deprecated method 'doComponentLayout' found for 'Ext.panel.Panel'.*/ },
                { message: /Call to deprecated method 'forceComponentLayout' found for 'Ext.panel.Panel'.*/ }
            ],
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    someCustomMethod: function () {
                        this.updateLayout();
                    },
                    someCustomMethod: function () {
                        var me = this;
                        me.updateLayout();
                    }
                });
            `
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4.1',
                    toVersion: '7.9'
                }
            },
            code: `
                Ext.clean([1, 2, '', 3]);
                var x = Ext;
                x.clean([1, 2, '', 3]);
            `,
            output: `
                Ext.Array.clean([1, 2, '', 3]);
                var x = Ext;
                x.Array.clean([1, 2, '', 3]);
            `,
            errors: 2
        }
    ]
});
